/* Game v4: explicit audio lifecycle, mixed phonics tasks and evidence-based rewards. */
const gameWaiters=new Set();
let gameCueToken=0,gameTimers=[],gameAudio=null,gameEffectAudio=null,gameLocked=false;
const gameDeck=AssessmentCore.createSoundDeck();
const rewardTiers=[{n:5,name:'Искра любопытства',symbol:'✦'},{n:10,name:'Солнечный исследователь',symbol:'☀'},{n:15,name:'Звезда звуков',symbol:'★'},{n:20,name:'Комета знаний',symbol:'✧'},{n:26,name:'Весь алфавит — мой!',symbol:'♛'}];
const fxWords={correct:['Динь-динь!','Вжух!','Прыг-скок!','Та-дам!','Звёздный звон!','Трень-трень!'],wrong:['Бойнг!','Тук-тук!','Фью-у!','Пам-пам!','Буль-буль!','Ва-у!']};
function cancelGameCue(){gameCueToken++;for(const cancel of [...gameWaiters])cancel(false);gameTimers.forEach(clearTimeout);gameTimers=[];gameAudio?.pause();window.speechSynthesis?.cancel();document.querySelectorAll('.is-listening').forEach(e=>e.classList.remove('is-listening'));}
function unlockGameAudio(){try{const C=window.AudioContext||window.webkitAudioContext;effectContext??=new C();effectContext.resume().catch(()=>{});const buffer=effectContext.createBuffer(1,1,effectContext.sampleRate),src=effectContext.createBufferSource();src.buffer=buffer;src.connect(effectContext.destination);src.start();}catch{}}
function gameSpeak(text,lang,token){return new Promise(resolve=>{if(token!==gameCueToken||!window.speechSynthesis){resolve(false);return;}const u=new SpeechSynthesisUtterance(text),voices=speechSynthesis.getVoices();u.lang=lang;const available=voices.filter(v=>v.lang.toLowerCase().startsWith(lang.slice(0,2)));const chosen=lang==='en-US'?chooseFriendlyVoice():available.find(v=>/Irina|Svetlana|Google|Alena/i.test(v.name))||available[0];if(chosen)u.voice=chosen;u.pitch=1.22;u.rate=lang==='ru-RU'?1:.86;let done=false;const finish=ok=>{if(done)return;done=true;clearTimeout(watch);gameWaiters.delete(finish);resolve(ok&&token===gameCueToken);};const watch=setTimeout(()=>finish(false),9000);gameWaiters.add(finish);u.onend=()=>finish(true);u.onerror=()=>finish(false);try{speechSynthesis.speak(u);}catch{finish(false);}});}
function gameClip(path,token){return new Promise(resolve=>{if(token!==gameCueToken){resolve(false);return;}gameAudio?.pause();const audio=new Audio(path);gameAudio=audio;audio.volume=1;let done=false;const finish=ok=>{if(done)return;done=true;clearTimeout(watch);gameWaiters.delete(finish);resolve(ok&&token===gameCueToken);};const watch=setTimeout(()=>{audio.pause();finish(false);},8000);gameWaiters.add(finish);audio.onended=()=>finish(true);audio.onerror=()=>finish(false);audio.play().catch(()=>finish(false));});}
function gamePause(ms,token){return new Promise(resolve=>{let done=false;const finish=ok=>{if(done)return;done=true;clearTimeout(timer);gameWaiters.delete(finish);resolve(ok&&token===gameCueToken);};const timer=setTimeout(()=>finish(true),ms);gameWaiters.add(finish);});}
function audioBlocked(){const e=document.getElementById('autoAudioNotice');if(e){e.hidden=false;e.innerHTML='<button class="primary" onclick="unlockGameAudio();autoGameCue()">▶ Включить звук</button><span>Браузеру нужен один клик. Дальше я буду говорить сам.</span>';}}
playFeedback=function(correct){const variant=gameDeck.next(correct),type=correct?'correct':'wrong';gameEffectAudio?.pause();gameEffectAudio=new Audio(`assets/effects/${type}-${variant}.wav`);gameEffectAudio.volume=.9;gameEffectAudio.play().catch(()=>{audioBlocked();toast('Браузер не включил звук. Нажми «Звук» и проверь воспроизведение.');});const el=document.getElementById('gameReaction');if(el){el.textContent=fxWords[type][variant];el.dataset.variant=type+'-'+variant;el.className='game-reaction '+(correct?'reaction-correct':'reaction-retry');}return variant;};
function toyChoice(letter,i,disabled=false){return `<button class="toy-answer toy-${i%3} ${disabled?'dimmed':''}" data-letter="${letter}" aria-label="Буква ${letter.toUpperCase()}" ${disabled?'disabled':''} onclick="answerDiagnostic('${letter}',this)"><span class="toy-letter" aria-hidden="true">${letter.toUpperCase()}<span class="toy-eyes"><i></i><i></i></span></span><span class="toy-lower" aria-hidden="true">${letter}</span><span class="toy-floor"></span><span class="toy-success">✦</span></button>`;}
function pictureArt(letter,extra=''){const p=GameCore.pictures[letter],x=(p.cell%4)*100/3,y=Math.floor(p.cell/4)*50;return `<span class="phonics-picture ${extra}" role="img" aria-label="${p.word}" style="background-position:${x}% ${y}%"></span>`;}
function gameInstruction(q){return ({name:'Найди букву!',letter:'Кто так звучит?',picture:'Найди картинку!',word:'Поймай первый звук!',audio:'Выбери её звук!'})[q.task];}
function gameSubtitle(q){return ({name:'Послушай имя. Нажми на букву.',letter:'Слушай звук. Лови букву!',picture:'Что начинается с этого звука?',word:'Послушай слово. Найди первую букву.',audio:'Послушай все три. Выбери один.'})[q.task];}
showDiagnosticIntro=function(){showModal(`<div class="game-intro"><div class="intro-orbi"><img src="assets/orbit-world.png" alt="Орби с книгой"></div><h2>Поиграем со звуками?</h2><p>Сначала — имена букв A–Z.<br>Потом — звуки вперемешку!</p><div class="difficulty-picker"><button class="difficulty-choice" onclick="modal.close();startDiagnostic('gentle')"><b>Первые шаги</b><span>Картинки и знакомые буквы</span></button><button class="difficulty-choice recommended" onclick="modal.close();startDiagnostic('explorer')"><b>Исследователь ✦</b><span>4 разные игры со звуками</span></button><button class="difficulty-choice" onclick="modal.close();startDiagnostic('challenge')"><b>Знаток</b><span>Похожие звуки. Слушай внимательно!</span></button></div><p class="intro-audio-note">♫ Орби озвучивает задания сам.<br>Награды: 5 · 10 · 15 · 20 · все 26 подряд.</p></div>`);};
startDiagnostic=function(difficulty='explorer'){clearTimeout(diagnosticTimer);cancelGameCue();unlockGameAudio();quiz=GameCore.create(difficulty);state.pendingQuiz=quiz;persist();renderDiagnostic();};
renderDiagnostic=function(){
 if(quiz?.schemaVersion!==4){showDiagnosticIntro();return;}clearTimeout(diagnosticTimer);cancelGameCue();heardQuestion=null;gameLocked=false;view='assessment';const q=quiz.items[quiz.index];if(!q){finishDiagnostic();return;}state.pendingQuiz=quiz;persist();document.getElementById('crumb').textContent=quiz.kind==='practice'?'Миссия: трудные звуки':'Остров звуков';
 const wrong=GameCore.events(quiz,q).filter(e=>!e.correct).map(e=>e.answer);let body='';
 if(['name','letter','word'].includes(q.task))body=`${q.task==='word'?`<div class="word-scene">${pictureArt(q.letter)}<button class="word-repeat" onclick="replayWord()" aria-label="Послушать слово">♫</button></div>`:''}<div class="toy-answers">${q.options.map((l,i)=>toyChoice(l,i,wrong.includes(l))).join('')}</div>`;
 if(q.task==='picture')body=`<div class="picture-options">${q.options.map((l,i)=>`<div class="picture-option ${wrong.includes(l)?'choice-is-wrong':''}"><button class="picture-select" aria-label="Картинка ${GameCore.pictures[l].word}" onclick="answerDiagnostic('${l}',this)" ${wrong.includes(l)?'disabled':''}>${pictureArt(l)}<span>Выбрать</span></button><button class="picture-listen" aria-label="Послушать слово ${GameCore.pictures[l].word}" onclick="listenPictureWord('${l}')">♫</button></div>`).join('')}</div>`;
 if(q.task==='audio')body=`<div class="audio-target" aria-label="Буква ${q.letter.toUpperCase()}">${toyChoice(q.letter,0).replace(/onclick="[^"]+"/,'disabled').replace('toy-answer','toy-answer target-toy')}</div><div class="audio-options">${q.options.map((l,i)=>`<div class="audio-option ${wrong.includes(l)?'choice-is-wrong':''}" data-option="${i}"><button class="audio-replay" onclick="listenSoundOption(${i})" aria-label="Послушать вариант ${i+1}"><span class="audio-bubble">♫</span><b>${i+1}</b></button><button class="audio-select" aria-label="Выбрать звук ${i+1}" onclick="answerDiagnostic('${l}',this)" ${wrong.includes(l)?'disabled':''}>Этот!</button></div>`).join('')}</div>`;
 const p=GameCore.progress(quiz);app.innerHTML=`<div class="sound-adventure"><div class="adventure-toolbar"><button class="secondary" onclick="exitQuiz()">Ⅱ Пауза</button><span>${quiz.kind==='practice'?'СПАСАЕМ ТРУДНЫЕ ЗВУКИ':q.mode==='name'?'ИМЕНА БУКВ · A–Z':'ЗВУКОВЫЕ ПРИКЛЮЧЕНИЯ'} <b>${quiz.index+1} / ${quiz.items.length}</b></span><button class="secondary" onclick="showAudioSettings()">♫ Звук</button></div><section class="adventure-stage"><div class="scene-cloud cloud-a"></div><div class="scene-cloud cloud-b"></div><div class="scene-hill hill-a"></div><div class="scene-hill hill-b"></div><span class="scene-spark spark-a">✦</span><span class="scene-spark spark-b">✧</span><div class="game-buddy"><div class="buddy-window"><img src="assets/orbit-world.png" alt="Орби — твой проводник"></div><span class="buddy-name">Орби</span><div class="buddy-speech">${quiz.kind==='practice'?'Вернём звукам<br>суперсилу!':'Слушай.<br>Пробуй.<br>Открывай!'}</div></div><div class="adventure-play"><div class="game-heading"><h1>${gameInstruction(q)}</h1><p>${gameSubtitle(q)}</p></div><div class="game-audio-bar"><button class="game-replay" onclick="autoGameCue()" aria-label="Повторить задание">♫ <span>Ещё раз</span></button><span id="cueStatus" role="status">Орби говорит…</span></div><div id="autoAudioNotice" hidden></div><div class="game-task" data-task="${q.task}">${body}</div><div id="gameReaction" class="game-reaction" aria-live="polite">${wrong.length?'Попробуй другой вариант!':'Я верю в тебя! ✦'}</div></div></section><div class="adventure-progress">${quiz.kind==='practice'?practiceProgress(p):diagnosticProgress()}</div>${rewardCollection()}</div>`;
 window.scrollTo(0,0);const token=gameCueToken;gameTimers.push(setTimeout(()=>{if(token===gameCueToken&&view==='assessment')autoGameCue();},180));
};
async function autoGameCue(){
 cancelGameCue();unlockGameAudio();const q=quiz?.items[quiz.index];if(!q)return;const token=gameCueToken,current=quiz;heardQuestion=null;const status=document.getElementById('cueStatus');if(status)status.textContent='Слушаем…';document.getElementById('autoAudioNotice').hidden=true;
 // Instructions are voiced for children; speech failure does not prevent a valid recorded cue.
 await gameSpeak(gameInstruction(q),'ru-RU',token);if(token!==gameCueToken||quiz!==current)return;let ok=true;
 if(q.task==='name')ok=await gameSpeak('The letter '+q.letter.toUpperCase()+'.','en-US',token);
 else if(q.task==='word')ok=await gameSpeak(GameCore.pictures[q.letter].word,'en-US',token);
 else if(q.task==='audio'){for(let i=0;i<q.options.length;i++){if(token!==gameCueToken)return;document.querySelectorAll('.audio-option').forEach(e=>e.classList.toggle('is-listening',Number(e.dataset.option)===i));if(status)status.textContent='Слушаем звук '+(i+1);const played=await gameClip('assets/phonemes/'+q.options[i]+'.mp3',token);ok=ok&&played;if(played)markOptionHeard(q,i);if(!await gamePause(220,token))return;}document.querySelectorAll('.audio-option').forEach(e=>e.classList.remove('is-listening'));}
 else ok=await gameClip('assets/phonemes/'+q.letter+'.mp3',token);
 if(token!==gameCueToken||quiz!==current)return;if(ok){heardQuestion=GameCore.key(q);quiz.replays??={};quiz.replays[heardQuestion]=(quiz.replays[heardQuestion]||0)+1;state.pendingQuiz=quiz;persist();if(status)status.textContent='Твой ход!';}else{if(status)status.textContent='Включим звук?';audioBlocked();}
}
async function listenSoundOption(i){const q=quiz.items[quiz.index],wasHeard=heardQuestion;cancelGameCue();const token=gameCueToken;document.querySelector(`.audio-option[data-option="${i}"]`)?.classList.add('is-listening');const ok=await gameClip('assets/phonemes/'+q.options[i]+'.mp3',token);if(token!==gameCueToken)return;document.querySelector(`.audio-option[data-option="${i}"]`)?.classList.remove('is-listening');if(ok)markOptionHeard(q,i);const all=(quiz.listenedOptions?.[GameCore.key(q)]||[]).length===3;heardQuestion=all?GameCore.key(q):wasHeard;const status=document.getElementById('cueStatus');if(status)status.textContent=heardQuestion?'Твой ход!':'Послушай все 3 звука';if(!ok)audioBlocked();}
async function listenPictureWord(l){const wasHeard=heardQuestion;cancelGameCue();await gameSpeak(GameCore.pictures[l].word,'en-US',gameCueToken);heardQuestion=wasHeard;}
async function replayWord(){return listenPictureWord(quiz.items[quiz.index].letter);}
answerDiagnostic=function(answer,button){
 if(gameLocked||view!=='assessment')return;const q=quiz.items[quiz.index],outcome=GameCore.answer(quiz,answer,heardQuestion===GameCore.key(q));if(!outcome.accepted){if(!heardQuestion){const status=document.getElementById('cueStatus');if(status)status.textContent='Сначала дослушай Орби!';}return;}
 cancelGameCue();state.pendingQuiz=quiz;persist();playFeedback(outcome.correct);if(quiz.kind!=='practice')refreshDiagnosticProgress();
 if(!outcome.correct){button.disabled=true;const card=button.closest('.audio-option,.picture-option')||button;card.classList.add(card.classList.contains('toy-answer')?'dimmed':'choice-is-wrong');const status=document.getElementById('cueStatus');if(status)status.textContent='Ещё попытка — ты справишься!';return;}
 gameLocked=true;document.querySelectorAll('.toy-answer,.audio-select,.picture-select').forEach(b=>b.disabled=true);button.classList.add('celebrate');const fresh=quiz.kind==='practice'?[]:collectMilestones(),run=quiz;
 const next=()=>{if(view!=='assessment'||quiz!==run)return;quiz.index++;state.pendingQuiz=quiz;persist();if(quiz.index<quiz.items.length)renderDiagnostic();else finishDiagnostic();};diagnosticTimer=setTimeout(()=>{if(view!=='assessment'||quiz!==run)return;if(fresh.length)showReward(fresh[0],next);else next();},1150);
};
diagnosticProgress=function(){const p=GameCore.progress(quiz);if(quiz.kind==='practice')return practiceProgress(p);const q=quiz.items[quiz.index];return `<section class="alphabet-dashboard" id="alphabetDashboard"><div class="alphabet-dashboard-head"><h3>${p.percent}% <small>пути пройдено</small></h3><div class="remaining-copy">Осталось <b>${ruCount(p.remainingQuestions,'задание','задания','заданий')}</b></div></div><div class="alphabet-meter" role="progressbar" aria-label="Прогресс диагностики" aria-valuenow="${p.answered}" aria-valuemin="0" aria-valuemax="52"><div style="width:${p.percent}%"></div></div><div class="alphabet-map">${p.letters.map(d=>`<button class="alphabet-stop ${d.problem?'has-problem':d.complete?'is-clean':q?.task==='audio'&&d.letter===q.letter?'is-current':''}" aria-label="${d.letter.toUpperCase()}: ${d.problem?'повторим':d.complete?'готово':'в пути'}" onclick="showLetterProgress('${d.letter}')"><b>${d.letter.toUpperCase()}</b><span class="letter-skill-dots"><i class="${d.name.errors.length?'dot-problem':d.name.completed?'dot-clean':''}"></i><i class="${d.sound.errors.length?'dot-problem':d.sound.completed?'dot-clean':''}"></i></span></button>`).join('')}</div><div class="streak-ladder"><b>${p.streak} подряд ✦</b>${rewardTiers.map(t=>`<span class="${p.streak>=t.n?'tier-complete':''}">${t.symbol} ${t.n}</span>`).join('')}</div><p class="progress-help">Две точки: имя и звук. Жёлтые буквы повторим в игре.</p></section>`;};
function practiceProgress(p){return `<section class="practice-meter"><h3>Спасено ${p.answered} из ${p.total} звуковых заданий ✦</h3><div class="alphabet-meter"><div style="width:${p.percent}%"></div></div></section>`;}
showLetterProgress=function(l){const report=AssessmentCore.summarize(quiz),d=report.detail.find(x=>x.letter===l);showModal(`<h2>Буква ${l.toUpperCase()}</h2><p>Имя: ${d.name.completed?(d.name.errors.length?'потренируем':'получилось!'):'впереди'}<br>Звук: ${d.sound.completed?(d.sound.errors.length?'потренируем':'получилось!'):'впереди'}</p><button class="primary" onclick="modal.close()">Продолжаем!</button>`);};
collectMilestones=function(){const p=GameCore.progress(quiz),fresh=[];for(const m of p.milestones){if(state.awards.some(a=>a.id===m.key))continue;const style=rewardTiers.findIndex(t=>t.n===m.threshold),tier=rewardTiers[style],award={id:m.key,name:tier.name,style,threshold:m.threshold,letters:m.letters,at:new Date().toISOString(),runStartedAt:quiz.startedAt};state.awards.push(award);fresh.push(award);}if(fresh.length)persist();return fresh;};
showReward=function(award,next){cancelGameCue();gameEffectAudio?.pause();gameEffectAudio=new Audio('assets/effects/reward.wav');gameEffectAudio.volume=.9;gameEffectAudio.play().catch(()=>{audioBlocked();toast('Браузер не включил звук. Нажми «Звук» и проверь воспроизведение.');});modal.classList.add('reward-dialog','epic-reward');const tier=award.threshold||award.letters.length,confetti=Array.from({length:65},(_,i)=>`<i style="--i:${i};--x:${i*31%100}%;--delay:${i%11*.13}s;--hue:${[40,150,265,20,185][i%5]}"></i>`).join('');showModal(`<div class="reward-celebration"><div class="reward-confetti" aria-hidden="true">${confetti}</div><div class="reward-rays"></div><div class="reward-floating-star one">✦</div><div class="reward-floating-star two">✧</div><span class="reward-announcement">${tier===26?'ВЕСЬ АЛФАВИТ!':'ВОТ ЭТО СЕРИЯ!'}</span>${medal(award.style)}<h2>${tier===26?'Все 26 подряд!':tier+' подряд!'}</h2><h3>${escapeHTML(award.name)}</h3><p>Имена и звуки — без ошибок!</p><button class="primary" onclick="modal.close()">${next?'Ура! Дальше!':'Класс!'} ✦</button><small>Медаль ждёт тебя в коллекции.</small></div>`);gameSpeak(tier===26?'Весь алфавит без ошибок! Невероятно!':tier+' букв подряд! Ты супер!','ru-RU',gameCueToken);modal.addEventListener('close',()=>{modal.classList.remove('reward-dialog','epic-reward');cancelGameCue();gameEffectAudio?.pause();next?.();},{once:true});};
rewardCollection=function(){return `<section class="reward-collection" id="rewards"><div class="section-head"><div><h2>Твои медали ✦</h2><p>5 · 10 · 15 · 20 · все 26 подряд</p></div></div><div class="reward-shelf">${rewardTiers.map((t,i)=>{const award=state.awards.slice().reverse().find(a=>(a.threshold||a.letters.length)===t.n);return award?`<button class="reward-badge" onclick="showSavedReward('${award.id}')">${medal(i,true)}<b>${t.n===26?'Все 26!':t.n+' подряд'}</b><span>${t.name}</span><small>Медаль твоя! ✓</small></button>`:`<div class="reward-badge reward-locked">${medal(i,true)}<b>${t.n===26?'Все 26!':t.n+' подряд'}</b><span>${t.name}</span><small>Впереди новое открытие</small></div>`;}).join('')}</div></section>`;};
finishDiagnostic=function(){clearTimeout(diagnosticTimer);cancelGameCue();if(quiz.kind==='practice'){finishPractice();return;}const report=AssessmentCore.summarize(quiz);if(!report.completed){renderDiagnostic();return;}report.schemaVersion=4;report.difficulty=quiz.difficulty;report.taskEvidence=quiz.answers.slice();state.diagnostic=report;delete state.pendingQuiz;state.sessions.push({type:'diagnostic',at:report.at,passed:report.passed,names:report.names,sounds:report.sounds,errorLetters:report.errorLetters,details:report.detail});persist();renderDiagnosticSummary(report);};
const oldSummary=renderDiagnosticSummary;
renderDiagnosticSummary=function(report){oldSummary(report);const hero=document.querySelector('.report-hero');if(hero&&report.errorLetters.length){hero.querySelector('.primary').outerHTML='<button class="primary" onclick="startRemedial()">Спасаем трудные звуки! ✦</button>';}const method=document.querySelector('.report-method');if(method)method.outerHTML='<details class="parent-details"><summary>Как считаем — для родителей</summary>'+method.outerHTML+'</details>';const table=document.querySelector('.mistakes-section');if(table)table.outerHTML=remedialHub(report);app.insertAdjacentHTML('beforeend',rewardCollection());};
function remedialHub(d){return `<section class="remedial-hub"><div class="remedial-title"><span>✦</span><div><h2>Вернём звукам суперсилу!</h2><p>Выбери героя или отправляйся спасать всех.</p></div></div><div class="rescue-letters">${d.detail.filter(x=>x.name.errors.length||x.sound.errors.length).map((x,i)=>`<button class="rescue-letter" onclick="startRemedial('${x.letter}')"><span class="rescue-character">${x.letter.toUpperCase()}</span><b>${x.name.errors.length&&x.sound.errors.length?'Имя и звук':x.name.errors.length?'Имя буквы':'Звук буквы'}</b><span>Поиграем! →</span></button>`).join('')}</div><button class="primary" onclick="startRemedial()">Спасти все трудные буквы! ↗</button><details class="parent-details"><summary>Подробности для родителей</summary>${errorTable(d).replace(/<h3>[^<]+<\/h3>/,'')}</details></section>`;}
function startRemedial(letter){clearTimeout(diagnosticTimer);cancelGameCue();unlockGameAudio();const source=state.diagnostic;if(!source?.detail)return;quiz=GameCore.practice(source,letter);if(!quiz.items.length){toast('Эти буквы уже получились без ошибок.');return;}state.pendingQuiz=quiz;persist();renderDiagnostic();}
function finishPractice(){state.practiceSessions??=[];const mistakes=quiz.answers.filter(e=>!e.correct);state.practiceSessions.push({at:new Date().toISOString(),letters:[...new Set(quiz.items.map(q=>q.letter))],answers:quiz.answers.slice(),errors:mistakes.length,sourceAt:quiz.sourceAt});delete state.pendingQuiz;persist();view='practice-result';app.innerHTML=`<section class="practice-victory"><div class="victory-spark">✦</div><h1>Миссия выполнена!</h1><p>Трудные звуки стали знакомее.</p><div class="victory-letters">${[...new Set(quiz.items.map(q=>q.letter))].map(l=>`<span>${l.toUpperCase()}</span>`).join('')}</div><div class="controls"><button class="primary" onclick="startRemedial()">Ещё приключение!</button><button class="secondary" onclick="navigate('results')">Мои результаты</button></div><p class="practice-parent-note">Практика сохранена отдельно. Исходные результаты диагностики не изменены.</p></section>${rewardCollection()}`;playFeedback(true);gameSpeak('Миссия выполнена! Молодец!','ru-RU',gameCueToken);}
results=function(){const d=state.diagnostic;if(d?.detail){renderDiagnosticSummary(d);return;}app.innerHTML=title('У каждого умения — своя история','Поиграем и узнаем твой уровень','Имена букв, картинки и звуковые загадки.')+`<div class="empty"><h2>Орби уже ждёт!</h2><button class="primary" onclick="showDiagnosticIntro()">Начать приключение →</button></div>`;};
exitQuiz=function(){clearTimeout(diagnosticTimer);cancelGameCue();state.pendingQuiz=quiz;persist();showModal('<h2>Отдохнём?</h2><p>Орби запомнил, где ты остановился.</p><div class="controls"><button class="primary" onclick="modal.close();navigate(\'home\')">В кабинет</button><button class="secondary" onclick="modal.close();renderDiagnostic()">Ещё играем!</button></div>');};
showAudioSettings=function(){showModal(`<h2>Слышно Орби?</h2><p>Задания звучат сами. Здесь можно проверить реакции.</p><div class="sound-tests"><button class="primary" onclick="playFeedback(true)">✦ Правильно!</button><button class="secondary" onclick="playFeedback(false)">↻ Ещё попытка!</button></div><p>Нажми несколько раз: каждый следующий звук отличается.</p><p class="credits-small">Phonics sounds: <a href="https://phonicademy.com" target="_blank" rel="noopener">Phonicademy</a>. Если звука нет, проверь громкость и разрешение воспроизведения в браузере.</p>`);};
continueLearning=function(){if(state.pendingQuiz?.schemaVersion===4){quiz=state.pendingQuiz;while(quiz.index<quiz.items.length&&GameCore.events(quiz,quiz.items[quiz.index]).some(e=>e.correct))quiz.index++;unlockGameAudio();if(quiz.index>=quiz.items.length)finishDiagnostic();else renderDiagnostic();return;}if(!state.diagnostic){showDiagnosticIntro();return;}openStage(level());};
const adventureNavigate=navigate;
navigate=function(next){cancelGameCue();clearTimeout(diagnosticTimer);adventureNavigate(next);const rewards=document.querySelectorAll('#rewards');rewards.forEach((e,i)=>{if(i>0)e.remove();});};
const renderAudioSettings=showAudioSettings;
showAudioSettings=function(){cancelGameCue();renderAudioSettings();modal.addEventListener('close',()=>{gameEffectAudio?.pause();if(view==='assessment'&&quiz?.schemaVersion===4)autoGameCue();},{once:true});};

function markOptionHeard(q,index){quiz.listenedOptions??={};const key=GameCore.key(q);quiz.listenedOptions[key]??=[];if(!quiz.listenedOptions[key].includes(index))quiz.listenedOptions[key].push(index);state.pendingQuiz=quiz;persist();}
